        method: 'crm.lists.update_list_filters',
        example:
          'require "hubspot_sdk"\n\nhubspot = HubSpotSDK::Client.new(access_token: "My Access Token")\n\nlist_update_response = hubspot.crm.lists.update_list_filters(\n  "listId",\n  filter_branch: {\n    filterBranches: [\n      {\n        filterBranches: [\n          {\n            filterBranches: [\n              {\n                filterBranches: [\n                  {\n                    filterBranches: [\n                      {\n                        eventTypeId: "eventTypeId",\n                        filterBranches: [\n                          {\n                            filterBranches: [\n                              {\n                                associationCategory: "associationCategory",\n                                associationTypeId: 0,\n                                filterBranches: [\n                                  {\n                                    filterBranches: [],\n                                    filterBranchOperator: "filterBranchOperator",\n                                    filterBranchType: :OR,\n                                    filters: [\n                                      {\n                                        filterType: :PROPERTY,\n                                        operation: {includeObjectsWithNoValueSet: true, operationType: :BOOL, operator: "operator", value: true},\n                                        property: "property"\n                                      }\n                                    ]\n                                  }\n                                ],\n                                filterBranchOperator: "filterBranchOperator",\n                                filterBranchType: :ASSOCIATION,\n                                filters: [\n                                  {\n                                    filterType: :PROPERTY,\n                                    operation: {includeObjectsWithNoValueSet: true, operationType: :BOOL, operator: "operator", value: true},\n                                    property: "property"\n                                  }\n                                ],\n                                objectTypeId: "objectTypeId",\n                                operator: "operator"\n                              }\n                            ],\n                            filterBranchOperator: "filterBranchOperator",\n                            filterBranchType: :PROPERTY_ASSOCIATION,\n                            filters: [\n                              {\n                                filterType: :PROPERTY,\n                                operation: {includeObjectsWithNoValueSet: true, operationType: :BOOL, operator: "operator", value: true},\n                                property: "property"\n                              }\n                            ],\n                            objectTypeId: "objectTypeId",\n                            operator: "operator",\n                            propertyWithObjectId: "propertyWithObjectId"\n                          }\n                        ],\n                        filterBranchOperator: "filterBranchOperator",\n                        filterBranchType: :UNIFIED_EVENTS,\n                        filters: [\n                          {\n                            filterType: :PROPERTY,\n                            operation: {includeObjectsWithNoValueSet: true, operationType: :BOOL, operator: "operator", value: true},\n                            property: "property"\n                          }\n                        ],\n                        operator: :HAS_COMPLETED\n                      }\n                    ],\n                    filterBranchOperator: "filterBranchOperator",\n                    filterBranchType: :RESTRICTED,\n                    filters: [\n                      {\n                        filterType: :PROPERTY,\n                        operation: {includeObjectsWithNoValueSet: true, operationType: :BOOL, operator: "operator", value: true},\n                        property: "property"\n                      }\n                    ]\n                  }\n                ],\n                filterBranchOperator: "filterBranchOperator",\n                filterBranchType: :NOT_ANY,\n                filters: [\n                  {\n                    filterType: :PROPERTY,\n                    operation: {includeObjectsWithNoValueSet: true, operationType: :BOOL, operator: "operator", value: true},\n                    property: "property"\n                  }\n                ]\n              }\n            ],\n            filterBranchOperator: "filterBranchOperator",\n            filterBranchType: :NOT_ALL,\n            filters: [\n              {\n                filterType: :PROPERTY,\n                operation: {includeObjectsWithNoValueSet: true, operationType: :BOOL, operator: "operator", value: true},\n                property: "property"\n              }\n            ]\n          }\n        ],\n        filterBranchOperator: "filterBranchOperator",\n        filterBranchType: :AND,\n        filters: [\n          {\n            filterType: :PROPERTY,\n            operation: {includeObjectsWithNoValueSet: true, operationType: :BOOL, operator: "operator", value: true},\n            property: "property"\n          }\n        ]\n      }\n    ],\n    filterBranchOperator: "filterBranchOperator",\n    filterBranchType: :OR,\n    filters: [\n      {\n        filterType: :PROPERTY,\n        operation: {includeObjectsWithNoValueSet: true, operationType: :BOOL, operator: "operator", value: true},\n        property: "property"\n      }\n    ]\n  }\n)\n\nputs(list_update_response)',
