        method: 'webhooks->updateSettings',
        example:
          "<?php\n\nrequire_once dirname(__DIR__) . '/vendor/autoload.php';\n\n$client = new Client(accessToken: 'My Access Token');\n\n$settingsResponse = $client->webhooks->updateSettings(\n  0, targetURL: 'targetUrl', throttling: ['maxConcurrentRequests' => 0]\n);\n\nvar_dump($settingsResponse);",
